from pathlib import Path
import hashlib
import re
import yaml

root = Path('/tmp/dfai-architecture-eval-qg0aqo4b/project')
source = root / 'docs/specs/prd/PRD-001.md'
expected_hash = '73a324099d4ea11fd4a99ab8f48f944ce36a2a0e955803de3f918bc9d5ac88ef'
assert hashlib.sha256(source.read_bytes()).hexdigest() == expected_hash
items = {}
for block in re.findall(r'```yaml items\n(.*?)\n```', source.read_text(), re.S):
    for entries in yaml.safe_load(block).values():
        for entry in entries:
            items[entry['id']] = entry
requirements = {key for key, value in items.items()
                if key.startswith(('FR-', 'NFR-')) and value['status'] == 'active'
                and value['release'] == 'current'}
documents = [root / 'docs/specs/add/ADD-001.md',
             *sorted((root / 'docs/specs/adr').glob('ADR-*.md'))]
ids = set()
for path in documents:
    content = path.read_text()
    header = yaml.safe_load(content.split('---', 2)[1])
    assert header['id'] not in ids
    ids.add(header['id'])
    assert header['version'] == 1
    for ref in header['upstream']:
        assert ref['id'] == 'PRD-001' and ref['version'] == 1
        if 'item' in ref:
            assert ref['item'] in requirements
    if header['id'] == 'ADD-001':
        assert header['upstream'][0]['hash'] == expected_hash
    assert content.count('```') % 2 == 0
assert ids == {'ADD-001', 'ADR-001', 'ADR-002', 'ADR-003'}
report = root / 'docs/specs/add/VERIFICATION-001.md'
for path in [*documents, report]:
    for target in re.findall(r'\[[^\]]+\]\(([^)]+)\)', path.read_text()):
        if not target.startswith(('https:', 'http:', '#')):
            assert (path.parent / target.split('#')[0]).is_file(), (path, target)
add = documents[0].read_text()
rows = re.findall(r'^\| ((?:FR|NFR)-\d+) \| (READY|BLOCKED) \| (.*)$', add, re.M)
assert len(rows) == len(requirements) == 6
assert {row[0] for row in rows} == requirements
assert dict((row[0], row[1]) for row in rows) == {
    'FR-001': 'BLOCKED', 'FR-002': 'READY', 'FR-003': 'READY',
    'NFR-001': 'READY', 'NFR-002': 'READY', 'NFR-003': 'READY'}
for item, status, detail in rows:
    if item.startswith('FR-'):
        assert all(nfr in detail for nfr in ('NFR-001', 'NFR-002', 'NFR-003'))
for path in [source, *documents]:
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    print(f'{digest}  {path.relative_to(root)}')
print('PASS: source hash, YAML metadata, IDs, upstream references, links, six readiness rows, and NFR inheritance')

